// AGENT_MODEL_OPTIONS moved to `renderer/agent-models.ts` — the chat composer
// picks from the same list, and a CLI fact does not belong to the graph feature.

/**
 * One typed connection rule (mirrors the daemon's `ConnectionRule` in
 * graphs.types.ts, plus a `description` for the info popup): "this side of a
 * node of some kind accepts/produces edges to nodes of `kind`". `required` =
 * the graph is invalid until such an edge exists; `multiple` = more than one
 * may attach (default: single).
 */
export interface ConnectionRule {
  /** Edge kind this rule governs — data-flow and call wires are separate ports. */
  edge: EdgeKind;
  kind: NodeKind;
  required?: boolean;
  multiple?: boolean;
  description: string;
}

/**
 * The connection contract per node kind — the renderer mirror of the
 * daemon's `NODE_CONNECTION_RULES` (which enforces it on save/run). Drives
 * the info popup's Inputs/Outputs sections and the canvas
 * `isValidConnection`. A future kind is one new entry here + one in the
 * daemon registry.
 *
 * Order matters: the FIRST rule per side is the painted top of the collapsed
 * handle stack (node-ports), so a collapsed drag lands on it — keep a data
 * rule first on every side, or collapsed drags stop being data-flow.
 */
export const NODE_CONNECTION_RULES: Record<
  NodeKind,
  { inputs: readonly ConnectionRule[]; outputs: readonly ConnectionRule[] }
> = {
  agent: {
    inputs: [
      {
        edge: 'data',
        kind: 'agent',
        multiple: true,
        description:
          "the final text of every upstream agent is appended to this node's prompt.",
      },
      {
        edge: 'data',
        kind: 'trigger',
        description:
          'fires this node with the run prompt — every run enters through a trigger.',
      },
      {
        edge: 'call',
        kind: 'agent',
        multiple: true,
        description:
          'agents wired here may invoke this node on demand during a run.',
      },
      {
        edge: 'instruction',
        kind: 'instruction',
        multiple: true,
        description:
          'every instruction block wired here is appended to this node’s turn.',
      },
    ],
    outputs: [
      {
        edge: 'data',
        kind: 'agent',
        multiple: true,
        description:
          "this node's final text feeds every downstream agent it connects to.",
      },
      {
        edge: 'call',
        kind: 'agent',
        multiple: true,
        description:
          'this node may invoke the connected agents via the call_agent tool.',
      },
    ],
  },
  trigger: {
    // Triggers are pure entry points: nothing may feed one, and firing fans
    // out to any number of agents. Call wires never touch triggers.
    inputs: [],
    outputs: [
      {
        edge: 'data',
        kind: 'agent',
        multiple: true,
        description: 'fires the connected agents with the run prompt.',
      },
    ],
  },
  instruction: {
    // A block is written, never produced: nothing may feed one, and it only
    // ever hands its text to agents. It runs nothing, so it has no output to
    // order and no turn to be called into.
    inputs: [],
    outputs: [
      {
        edge: 'instruction',
        kind: 'agent',
        multiple: true,
        description:
          'appends this block’s text to every connected agent’s turn — it never runs itself.',
      },
    ],
  },
};

/**
 * The React Flow handle id for one connection rule — geniro's
 * `${dir}-${rule.type}-${slug(rule.value)}` scheme extended with the edge
 * kind. Every rule renders its own handle under this id (collapsed and
 * expanded alike), and because the registry holds at most ONE rule per
 * (side, edge kind, peer kind), an edge's handles are fully derivable from
 * its kind + endpoint kinds — so ports never need to be persisted in the
 * YAML (which is also why this rename was free: handles never hit disk).
 */
export function makeHandleId(
  dir: 'source' | 'target',
  edge: EdgeKind,
  kind: NodeKind,
): string {
  return `${dir}-${edge}-${kind}`;
}

/**
 * The kinds that are NOT data flow. Each carries its own React Flow `type`,
 * spelled exactly as the edge kind, which is also what selects its registered
 * component (`annotation-edge.tsx`). A data edge carries no type at all —
 * React Flow's default — so "no type" and "data" stay the same statement.
 */
export const ANNOTATION_EDGE_KINDS = [
  'call',
  'instruction',
] as const satisfies readonly EdgeKind[];

/** An edge kind that is not data flow — the type the list narrows to. */
export type AnnotationEdgeKind = (typeof ANNOTATION_EDGE_KINDS)[number];

/**
 * The one membership test over that list. It is a type GUARD rather than a
 * boolean so the two mappings below need no cast: derived from the list, so
 * renaming an `EdgeKind` member breaks here instead of silently leaving a
 * mapping that returns a kind which no longer exists.
 */
export function isAnnotationEdgeKind(
  value: string | undefined,
): value is AnnotationEdgeKind {
  return ANNOTATION_EDGE_KINDS.some((kind) => kind === value);
}

/**
 * The canvas edge ⇄ EdgeKind discriminator, in ONE place. Every canvas
 * producer/consumer routes through this pair — re-deriving the mapping inline
 * is how a rename silently misses a site.
 */
export function flowEdgeKind(edge: { type?: string }): EdgeKind {
  return isAnnotationEdgeKind(edge.type) ? edge.type : 'data';
}

/** Spreadable inverse of {@link flowEdgeKind} for building canvas edges. */
export function flowEdgeType(edgeKind: EdgeKind): {
  type?: AnnotationEdgeKind;
} {
  return edgeKind === 'data' ? {} : { type: edgeKind };
}

/**
 * The edge kind a drag is wiring, read off the handles it grabbed: an
 * annotation handle makes it that kind of wire (the other end may be a
 * collapsed stack's data handle — onConnect normalizes the pair afterwards).
 * Everything else — collapsed pills, missing handle ids — stays data flow,
 * which is what makes the collapsed-drag-is-data-flow rule hold.
 *
 * **The SOURCE end decides.** The two ends can name different annotation
 * kinds — an instruction block's only output dropped onto an agent's expanded
 * `call` row — and answering with the target's kind yields a wire the rules
 * refuse, so `isValidConnection` blocks the drop and the user gets silence
 * instead of the edge they aimed at.
 */
export function connectionEdgeKind(
  sourceHandle: string | null | undefined,
  targetHandle: string | null | undefined,
): EdgeKind {
  const edgeOf = (handle: string | null | undefined): string | undefined =>
    handle?.split('-')[1];
  const source = edgeOf(sourceHandle);
  if (isAnnotationEdgeKind(source)) {
    return source;
  }
  const target = edgeOf(targetHandle);
  return isAnnotationEdgeKind(target) ? target : 'data';
}

/**
 * Whether an edge of `edge` kind `source → target` is legal under the
 * connection rules: the source kind must list (edge, target kind) in its
 * `outputs` AND the target kind must list (edge, source kind) in its
 * `inputs` (both sides agree) — the same pairing the daemon's
 * `validateEdgeRules` enforces on save. Unknown kinds refuse the connection
 * rather than throwing: on the canvas this is a live drag predicate, not a
 * validation gate.
 */
export function canConnect(
  edgeKind: EdgeKind,
  sourceKind: string,
  targetKind: string,
  rules: Record<
    string,
    {
      inputs: readonly { edge: string; kind: string }[];
      outputs: readonly { edge: string; kind: string }[];
    }
  > = NODE_CONNECTION_RULES,
): boolean {
  const out = rules[sourceKind]?.outputs.some(
    (r) => r.edge === edgeKind && r.kind === targetKind,
  );
  const inp = rules[targetKind]?.inputs.some(
    (r) => r.edge === edgeKind && r.kind === sourceKind,
  );
  return Boolean(out && inp);
}

/**
 * The node kinds the builder can place. Derived from the generated
 * `WorkflowNode` union rather than restated, so a kind added on the daemon
 * turns into a type error in `NODE_TYPE_SCHEMAS` / `NODE_CONNECTION_RULES`
 * (both keyed by this) the moment the client is regenerated.
 */
export type NodeKind = WorkflowNode['kind'];

/**
 * Trigger kinds a trigger node may carry, read off the generated enum so the
 * palette offers exactly what the daemon accepts.
 */
export const TRIGGER_KINDS: readonly TriggerKind[] = Object.values(TriggerKind);
